def nearlyLucky(fortuna):
    count = 0

    while fortuna > 0:
        if fortuna % 10 == 4 or fortuna % 10 == 7:
            count += 1
        fortuna //= 10

    return count == 4 or count == 7

if __name__ == "__main__":
    fortuna = int(input())
    print("YES" if nearlyLucky(fortuna) else "NO")

def lucky(money):
    count = 0

    while money > 0:
        if money % 10 == 4 or money % 10 == 7:
            count += 1
        money //= 10

    return count in (4,7)
if __name__ == "__main__":
    money = int(input())
    print ("YES" if lucky(money) else "NO")

def nearlyLucky(money):
    count = 0

    while money > 0:
        if money % 10 == 4 or money % 10 == 7:
            count += 1
        money //= 10

    return count in (4, 7)

if __name__ == "__main__":
    money = int(input())
    print("YES" if nearlyLucky(money) else "NO")

def code(*args):

    num = args[0]
    digit = 0

    while (num > 0):
        last_digit = num % 10
        if (last_digit == 4 or last_digit == 7):
            digit += 1            
        num //= 10

    if (digit == 4 or digit == 7):
        return "YES"

    return "NO"

def is_nearly_lucky(num):
    count = 0
    while num > 0:
        digit = num % 10
        if digit == 4 or digit == 7:
            count += 1
        num //= 10
    return is_lucky(count)

