def isLucky(num):
    num = str(num)
    Lucky = 0
    for i in range(0, len(num)):
        if (num[i] == "4" or num[i] == "7"):
            Lucky += 1

    return "YES" if Lucky == 7 or Lucky == 4 else "NO"

