def isLuckyNum(s):
    cnt = 0
    for ch in s:
        if ch in ['4', '7']:
            cnt += 1
    for ch in str(cnt):
        if ch not in ['4', '7']:
            return "NO"
    return "YES"

s = input()
print(isLuckyNum(s))

